package com.petcare.backend.service.impl;
import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.petcare.backend.dto.emr.*;import com.petcare.backend.dto.emr.request.*;import com.petcare.backend.exception.BadRequestException;import com.petcare.backend.model.*;import com.petcare.backend.repository.*;import com.petcare.backend.security.UserPrincipal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.*;
@ExtendWith(MockitoExtension.class) @MockitoSettings(strictness=org.mockito.quality.Strictness.LENIENT) class EmrRecordServiceImplTest {@Mock PetRepository pets;@Mock UserRepository users;@Mock PetCoParentRepository coparents;@Mock EmrRecordRepository records;@Mock PetTimelineEventRepository timeline;@Mock ObjectMapper mapper;@Mock UserPrincipal principal;EmrRecordServiceImpl service;@BeforeEach void init(){service=new EmrRecordServiceImpl(pets,users,coparents,records,timeline,mapper);when(principal.getId()).thenReturn(1L);when(records.save(any())).thenAnswer(i->{EmrRecord r=i.getArgument(0);r.setId(5L);return r;});} Pet pet(long owner){Pet p=new Pet();p.setId(2L);p.setName("Milo");User u=new User();u.setId(owner);p.setOwner(u);return p;} CreateEmrRecordRequest req(List<EmrAttachmentDto>a){CreateEmrRecordRequest r=new CreateEmrRecordRequest();r.setPetId(2L);r.setRecordType(EmrRecord.RecordType.visit);r.setVisitDate(LocalDate.now());r.setDiagnosis("  cold  ");r.setClinicName(" Clinic ");r.setVetName(" ");r.setNotes(" note ");r.setAttachments(a);return r;} void accessible(Pet p){when(pets.findByIdAndAccessibleByUserId(2L,1L)).thenReturn(Optional.of(p));}
@Test void createOwnerWithEmptyAttachmentsTrimsAndCreatesTimeline(){Pet p=pet(1);accessible(p);User u=new User();u.setId(1L);when(users.findById(1L)).thenReturn(Optional.of(u));var out=service.createEmrRecord(principal,req(null));assertThat(out.getDiagnosis()).isEqualTo("cold");ArgumentCaptor<EmrRecord> c=ArgumentCaptor.forClass(EmrRecord.class);verify(records).save(c.capture());assertThat(c.getValue().getAttachments()).isNull();assertThat(c.getValue().getClinicName()).isEqualTo("Clinic");verify(timeline).save(argThat(e->e.getReferenceId().equals(5L)&&e.getSummary().contains("Clinic")));}
@Test void createCoversPetViewerUserAndSerializationErrors(){when(pets.findByIdAndAccessibleByUserId(2L,1L)).thenReturn(Optional.empty());assertThatThrownBy(()->service.createEmrRecord(principal,req(List.of()))).isInstanceOf(BadRequestException.class);Pet p=pet(9);accessible(p);assertThatThrownBy(()->service.createEmrRecord(principal,req(List.of()))).isInstanceOf(BadRequestException.class);Pet editor=pet(9);PetCoParent cp=new PetCoParent();cp.setRole(PetCoParent.CoParentRole.editor);when(pets.findByIdAndAccessibleByUserId(2L,1L)).thenReturn(Optional.of(editor));when(coparents.findByPetIdAndUserId(2L,1L)).thenReturn(Optional.of(cp));when(users.findById(1L)).thenReturn(Optional.empty());assertThatThrownBy(()->service.createEmrRecord(principal,req(List.of()))).isInstanceOf(BadRequestException.class);User u=new User();u.setId(1L);when(users.findById(1L)).thenReturn(Optional.of(u));EmrAttachmentDto a=new EmrAttachmentDto();a.setFileName("a");a.setFileUrl("u");a.setFileType("t");try{when(mapper.writeValueAsString(any())).thenThrow(new JsonProcessingException("bad"){});}catch(JsonProcessingException e){throw new RuntimeException(e);}assertThatThrownBy(()->service.createEmrRecord(principal,req(List.of(a)))).isInstanceOf(BadRequestException.class);}
@Test void editorCanCreateWithSerializedAttachmentsAndBlankClinic(){Pet editor=pet(9);PetCoParent cp=new PetCoParent();cp.setRole(PetCoParent.CoParentRole.editor);when(pets.findByIdAndAccessibleByUserId(2L,1L)).thenReturn(Optional.of(editor));when(coparents.findByPetIdAndUserId(2L,1L)).thenReturn(Optional.of(cp));User u=new User();u.setId(1L);when(users.findById(1L)).thenReturn(Optional.of(u));EmrAttachmentDto a=new EmrAttachmentDto();a.setFileName("a");a.setFileUrl("u");a.setFileType("t");try{when(mapper.writeValueAsString(any())).thenReturn("[{}]");}catch(Exception e){throw new RuntimeException(e);}CreateEmrRecordRequest request=req(List.of(a));request.setClinicName(" ");assertThat(service.createEmrRecord(principal,request).getAttachments()).containsExactly(a);verify(records).save(argThat(r->"[{}]".equals(r.getAttachments())));verify(timeline).save(argThat(e->e.getSummary().contains("được khám bệnh:")));}
@Test void listAndDetailCoverEmptyCorruptJsonMissingAndAccessible(){Pet p=pet(1);accessible(p);when(records.findByPetIdOrderByVisitDateDescCreatedAtDesc(2L)).thenReturn(List.of());assertThat(service.getEmrRecordsByPet(principal,2L)).isEmpty();EmrRecord r=new EmrRecord();r.setId(5L);r.setPet(p);User creator=new User();creator.setId(1L);r.setCreatedBy(creator);r.setAttachments("bad");r.setDiagnosis("d");r.setVisitDate(LocalDate.now());try{when(mapper.readValue(eq("bad"),any(TypeReference.class))).thenThrow(new JsonProcessingException("bad"){});}catch(JsonProcessingException e){throw new RuntimeException(e);}when(records.findByPetIdOrderByVisitDateDescCreatedAtDesc(2L)).thenReturn(List.of(r));assertThat(service.getEmrRecordsByPet(principal,2L)).singleElement().satisfies(x->assertThat(x.getAttachments()).isEmpty());when(records.findById(9L)).thenReturn(Optional.empty());assertThatThrownBy(()->service.getEmrRecordById(principal,9L)).isInstanceOf(BadRequestException.class);when(records.findById(5L)).thenReturn(Optional.of(r));assertThat(service.getEmrRecordById(principal,5L).getId()).isEqualTo(5L);}
}
